import{bV as t,aL as l,u as e,G as i}from"./chunks/framework.BfzMay2U.js";const _=JSON.parse('{"title":"swot态势分析法","description":"","frontmatter":{"title":"swot态势分析法","date":"2026-09-15T16:55:10.000Z"},"headers":[],"relativePath":"ai/swot.md","filePath":"ai/swot.md"}'),o={name:"ai/swot.md"};function r(s,a,n,d,c,u){return l(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="swot-态势分析法" tabindex="-1">SWOT 态势分析法 <a class="header-anchor" href="#swot-态势分析法" aria-label="Permalink to &quot;SWOT 态势分析法&quot;">​</a></h1><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><blockquote><p>用来确定企业自身竞争优势、劣势、外部市场的机会和威胁，从而将公司的战略与公司内部资源、外部环境有机结合起来的一种科学的分析方法。</p></blockquote><ul><li>Strength：优势</li><li>Weakness：劣势</li><li>Opportunity：机会</li><li>Threats：威胁</li></ul><h2 id="案例" tabindex="-1">案例 <a class="header-anchor" href="#案例" aria-label="Permalink to &quot;案例&quot;">​</a></h2><ul><li><p>个人做技术<code>Leader</code>能力分析（工作 3 年，高级 java，技术能力不错，项目组长刚离职）</p><ul><li>优势：技术不错、对公司业务熟悉（个人内部）</li><li>劣势：项目管理能力不足、PPT 汇报能力不足（个人内部）</li><li>机会：独立负责的项目把控、直接和领导汇报、成为管理层（公司外部）</li><li>威胁：项目的规范机制还没有建立、项目的核心难点还没攻破、加班比较多（公司外部）</li></ul></li><li><p>技术解决方案分析（团队熟悉 RabbitMQ、新来的组长熟悉 RocketMQ，技术选型考虑）</p><ul><li>优势：RabbitMQ 团队多人使用过、AMQP 跨语言、模型 API 丰富（团队内部）</li><li>劣势：阅读过源码的人较少，Erlang 开发，二次修改不容易，项目组长对这个不熟悉（团队内部）</li><li>机会：项目可以快速上线，减少踩坑（团队外部）</li><li>威胁：未来可能有更强大的 MQ 产品出现或公司改动架构（团队外部）</li></ul></li></ul><p><strong>总结：根据 SWOT 进行充分分析，然后进行取舍选择，考虑更全，做事回答就会更有条理了</strong></p>',7)])])}const h=t(o,[["render",r]]);export{_ as __pageData,h as default};
